import heapq

def min_completion_time(tasks: list[int], k: int) -> int:
    if not tasks:
        return 0
    if k >= len(tasks):
        return max(tasks)

    heap = [0] * k
    for t in sorted(tasks, reverse=True):
        smallest = heapq.heappop(heap)
        heapq.heappush(heap, smallest + t)

    return max(heap)
